// Parse + validate input. Anything not a YouTube URL gets rejected here.
const body = $input.first().json.body ?? $input.first().json;
const url = (body.url ?? '').toString().trim();
const m = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/shorts\/)([A-Za-z0-9_-]{6,})/);
if (!m) {
  throw new Error('invalid_youtube_url');
}
return [{
  json: {
    url,
    video_id: m[1],
    voice_template_id: body.voice_template_id ?? null,
    languages: Array.isArray(body.languages) && body.languages.length ? body.languages : ['en', 'nl'],
    extras: Array.isArray(body.extras) ? body.extras : ['linkedin', 'seo'],
    started_at: new Date().toISOString(),
  },
}];

// If cache hit AND fetched within last 24h, skip fetch_meta + transcript.
const row = $input.first().json;
const fresh = row && row.fetched_at && (Date.now() - new Date(row.fetched_at).getTime()) < 24 * 3600 * 1000;
const ctx = $('parse_input').first().json;
return [{
  json: {
    ...ctx,
    cache_hit: !!fresh,
    cached_source_id: fresh ? row.id : null,
    cached_meta: fresh ? {
      title: row.title,
      channel: row.channel,
      duration_seconds: row.duration_seconds,
      thumbnail_url: row.thumbnail_url,
      published_at: row.published_at,
    } : null,
    cached_transcript: fresh ? {
      transcript_text: row.transcript_text,
      transcript_segments: row.transcript_segments,
      transcript_source: row.transcript_source,
    } : null,
  },
}];

// Persist the freshly-fetched meta + transcript to hvl_youtube_sources.
// Skips if we're on a cache hit.
const ctx = $('cache_branch').first().json;
if (ctx.cache_hit) {
  return [{ json: { ...ctx, source_id: ctx.cached_source_id } }];
}
const meta = $('step_1_fetch_meta').first().json;
const transcript = $('step_2_transcript').first().json;
return [{
  json: {
    ...ctx,
    meta: { ...meta },
    transcript: { ...transcript },
    upsert_payload: {
      url: ctx.url,
      video_id: ctx.video_id,
      title: meta.title,
      channel: meta.channel,
      duration_seconds: meta.duration_seconds,
      thumbnail_url: meta.thumbnail_url,
      published_at: meta.published_at,
      transcript_text: transcript.transcript_text,
      transcript_segments: transcript.transcript_segments,
      transcript_source: transcript.transcript_source,
      cost_usd: (transcript.cost_usd ?? 0),
      fetched_at: new Date().toISOString(),
    },
  },
}];

