// Assemble the final draft payload from all upstream steps.
const ctx = $('build_cache_payload').first().json;
const draftEn = $('step_6_draft_en').first().json;
const draftNl = $('step_7_draft_nl').first().json;
const seo = $('step_8a_seo').first().json;
const review = $('step_8b_review').first().json;
const liEn = $('step_9a_linkedin_en').first().json.message ?? $('step_9a_linkedin_en').first().json.text ?? '';
const liNl = $('step_9b_linkedin_nl').first().json.message ?? $('step_9b_linkedin_nl').first().json.text ?? '';
const hero = $('step_hero').first().json?.image_url ?? null;
const voiceFit = Math.round(
  (review.dimensions?.find?.((d) => /voice|style|tone/i.test(d.name))?.score) ?? review.total_score ?? 0
);
const readability = Math.round(
  review.dimensions?.find?.((d) => /read|clarity|flow/i.test(d.name))?.score ?? 70
);
const seoScore = Math.round(
  review.dimensions?.find?.((d) => /seo|find|keyword/i.test(d.name))?.score ?? 75
);
const sourceId = ctx.cache_hit ? ctx.cached_source_id : $('cache_upsert').first().json.id;
return [{
  json: {
    title: draftEn.title,
    slug: seo.canonical_url?.replace(/^\/writing\//, '') ?? draftEn.suggested_slug,
    content: draftEn.content,
    content_nl: draftNl.content,
    excerpt: draftEn.excerpt,
    excerpt_nl: draftNl.excerpt,
    category: ($('step_3_topics').first().json.suggested_category ?? 'tech'),
    tags: draftEn.suggested_tags ?? [],
    status: 'draft',
    voice_template_id: ctx.voice_template_id,
    hero_image_url: hero,
    meta_title: seo.meta_title,
    meta_description: seo.meta_description,
    source_youtube_id: sourceId,
    // The remaining fields are returned in the response but not all are
    // columns on hvl_blog_articles — they live in the assembled draft
    // object the frontend receives.
    _assembled: {
      title_en: draftEn.title,
      title_nl: draftNl.title,
      content_en: draftEn.content,
      content_nl: draftNl.content,
      excerpt_en: draftEn.excerpt,
      excerpt_nl: draftNl.excerpt,
      slug: seo.canonical_url?.replace(/^\/writing\//, '') ?? draftEn.suggested_slug,
      category: ($('step_3_topics').first().json.suggested_category ?? 'tech'),
      tags: draftEn.suggested_tags ?? [],
      voice_template_id: ctx.voice_template_id,
      voice_fit: voiceFit,
      seo_score: seoScore,
      readability,
      forbidden_terms_found: review.forbidden_terms_found ?? [],
      linkedin_en: liEn,
      linkedin_nl: liNl,
      hero_image_url: hero,
      word_count_en: draftEn.word_count ?? 0,
      word_count_nl: draftNl.word_count ?? 0,
      source_youtube_id: sourceId,
    },
  },
}];

// Final shape: matches the AssembledDraft type the React modal expects,
// plus the post_id from step 10. The frontend pulls .post_id and .draft.
const saved = $input.first().json;
const assembled = $('assemble').first().json._assembled;
const sourceId = $('assemble').first().json.source_youtube_id;
return [{
  json: {
    type: 'done',
    post_id: saved.id,
    elapsed_ms: Date.now() - new Date($('parse_input').first().json.started_at).getTime(),
    draft: {
      ...assembled,
      source_youtube_id: sourceId,
    },
  },
}];
